#!/bin/bash ############################################## # SDP Monitor - Complete Monitoring Wrapper # Runs monitoring + database loading + upload ############################################## SCRIPT_DIR="$HOME" DASHBOARD_SERVER="root@10.78.114.31" echo "============================================" echo "SDP Monitoring - Complete Cycle" echo "============================================" echo "" # Step 1: Run main monitoring script echo "[1/3] Running ERE monitoring..." if [ -f "$SCRIPT_DIR/ere_monitor_fast.sh" ]; then bash "$SCRIPT_DIR/ere_monitor_fast.sh" MONITOR_EXIT=$? echo " Monitoring complete (exit code: $MONITOR_EXIT)" else echo " ERROR: ere_monitor_fast.sh not found" exit 1 fi echo "" # Step 2: Load data into database echo "[2/3] Loading data into database..." if [ -f "$SCRIPT_DIR/db_loader.sh" ]; then bash "$SCRIPT_DIR/db_loader.sh" if [ $? -eq 0 ]; then echo " Database loaded successfully" else echo " WARNING: Database loading failed" fi else echo " WARNING: db_loader.sh not found - skipping database" fi echo "" # Step 3: Upload database to dashboard server echo "[3/3] Uploading to dashboard server..." DB_FILE="$HOME/sdp_monitor.db" if [ ! -f "$DB_FILE" ]; then echo " ERROR: Database file not found: $DB_FILE" echo " Skipping upload" else # Upload database if scp -q -o ConnectTimeout=10 -o StrictHostKeyChecking=no \ "$DB_FILE" "${DASHBOARD_SERVER}:/var/www/html/sdp-monitor/data/sdp_monitor.db"; then echo " Database uploaded to ${DASHBOARD_SERVER}" # Set permissions on remote server ssh -q -o ConnectTimeout=10 -o StrictHostKeyChecking=no "$DASHBOARD_SERVER" \ "chown apache:apache /var/www/html/sdp-monitor/data/sdp_monitor.db && \ chmod 664 /var/www/html/sdp-monitor/data/sdp_monitor.db" 2>/dev/null echo " Permissions set on remote server" else echo " ERROR: Failed to upload database" echo " Check SSH key access to ${DASHBOARD_SERVER}" fi fi echo "" echo "============================================" echo "Monitoring Cycle Complete" echo "============================================" echo "" echo "Reports:" echo " Alarms: $HOME/ere_alarms_latest.txt" echo " Stats: $HOME/ere_stats_latest.txt" echo " Database: $DB_FILE" echo " Dashboard: http://10.78.114.31/sdp-monitor/" echo "" # Exit with monitoring script's exit code exit $MONITOR_EXIT